(function(){
  if(window.__QMES_RECIPE_CHEM_MASTER_V3__) return;
  window.__QMES_RECIPE_CHEM_MASTER_V3__=true;
  const KEY='qmes-bom-local-v1';
  let customHost=null,nativeHost=null,selectedId=null;
  const empty='등록된 데이터가 없습니다.';
  const load=()=>{try{const v=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(v)?v:[]}catch(e){return[]}};
  const saveAll=v=>localStorage.setItem(KEY,JSON.stringify(v));
  const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  function table(head,bodyId,cols){return `<div class="qbe-table-wrap"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody id="${bodyId}"><tr><td colspan="${cols}" style="text-align:center;color:#94a3b8;padding:24px">${empty}</td></tr></tbody></table></div>`}
  function html(){return `<div class="qmes-business-extension qbe-chemical-master">
    <div class="qbe-title-row"><div><h1 class="qbe-title">Recipe / BOM Master</h1><div class="qbe-subtitle">제품별 BOM · Recipe Revision · 표준 배합 · 공정 Routing을 통합 관리합니다.</div><div style="margin-top:5px;font-size:11px;color:#64748b">제품 → Revision → Formula / Routing → MRP → 작업지시 → 생산 LOT</div></div></div>
    <div class="qbe-card" style="padding:10px 12px;margin-bottom:12px"><div style="display:flex;gap:7px;flex-wrap:wrap;align-items:center"><button class="qbe-primary" data-bom-act="search">조회</button><button class="qbe-primary" data-bom-act="add">+ 추가</button><button class="qbe-primary" data-bom-act="save">저장</button><button class="qbe-primary" data-bom-act="delete" style="background:#64748b">삭제</button><button class="qbe-primary" data-bom-act="copy" style="background:#475569">BOM 복사</button><button class="qbe-primary" data-bom-act="revision" style="background:#f59e0b">BOM 개정</button><button class="qbe-primary" data-bom-act="print" style="background:#475569">인쇄</button><span id="qbm-message" style="font-size:12px;font-weight:800;color:#2563eb;margin-left:8px"></span></div></div>
    <div style="display:grid;grid-template-columns:minmax(250px,.55fr) minmax(600px,1.45fr);gap:12px">
      <div class="qbe-card"><div class="qbe-card-head"><h2>제품 목록</h2><span class="qbe-hint">Product Master</span></div>${table(['제품코드','제품명','고객사','Grade'],'qbm-products',4)}</div>
      <div class="qbe-card"><div class="qbe-card-head"><h2>Recipe / BOM 개정 목록</h2><span class="qbe-hint">Revision History</span></div>${table(['Revision','변경내용','기준 Batch','예상수율','적용일','상태','승인'],'qbm-revisions',7)}</div>
    </div>
    <div class="qbe-card"><div class="qbe-card-head"><h2>선택 BOM 기본정보</h2><span class="qbe-hint">Master Data</span></div><div class="qbe-form-grid">
      <div class="qbe-field"><label>제품코드</label><input data-f="productCode" placeholder="제품코드"></div><div class="qbe-field"><label>제품명</label><input data-f="productName" placeholder="제품명"></div><div class="qbe-field"><label>고객사</label><input data-f="customer" placeholder="고객사"></div><div class="qbe-field"><label>제품 Grade</label><input data-f="grade" placeholder="Grade / 규격"></div>
      <div class="qbe-field"><label>Recipe No.</label><input data-f="recipeNo" placeholder="RCP-001"></div><div class="qbe-field"><label>Revision</label><input data-f="revision" placeholder="Rev.01"></div><div class="qbe-field"><label>기준 Batch Size (kg)</label><input data-f="batchSize" type="number" placeholder="1000"></div><div class="qbe-field"><label>예상 수율 (%)</label><input data-f="yield" type="number" placeholder="100.00"></div>
      <div class="qbe-field"><label>적용일</label><input data-f="effectiveDate" type="date"></div><div class="qbe-field"><label>상태</label><select data-f="status"><option>작성중</option><option>검토중</option><option>승인</option><option>사용중</option><option>폐기</option></select></div><div class="qbe-field"><label>변경내용</label><input data-f="changeNote" placeholder="개정 사유 / 변경내용"></div><div class="qbe-field"><label>작성 / 검토 / 승인</label><input readonly placeholder="전자결재 연동"></div>
    </div></div>
    <div class="qbe-card"><div class="qbe-card-head"><div style="display:flex;gap:5px;flex-wrap:wrap" class="qbm-tabs"><button class="qbe-primary" data-tab="formula">① 표준 배합표</button><button class="qbe-primary" data-tab="routing" style="background:#64748b">② 공정조건</button><button class="qbe-primary" data-tab="ctq" style="background:#64748b">③ CTQ / 검사기준</button><button class="qbe-primary" data-tab="change" style="background:#64748b">④ 변경이력</button><button class="qbe-primary" data-tab="lot" style="background:#64748b">⑤ 생산 LOT 이력</button></div><span class="qbe-hint">화학 제조 BOM</span></div>
      <div data-pane="formula"><div class="qbe-card-head"><h2>표준 배합표 (Formula)</h2><span class="qbe-hint">배합비 합계 100% 자동 검증</span></div>${table(['순번','원료코드','원료명','구분','규격/Grade','배합비 %','기준량 kg','허용오차','투입순서','투입공정','CTQ','대체원료'],'qbm-formula',12)}</div>
      <div data-pane="routing" style="display:none"><div class="qbe-card-head"><h2>공정 Routing / 조건</h2></div>${table(['공정순서','공정명','설비','시간','RPM','온도','압력','관리기준','검사'],'qbm-routing',9)}</div>
      <div data-pane="ctq" style="display:none"><div class="qbe-card-head"><h2>CTQ / 검사기준 연계</h2></div>${table(['검사항목','규격','단위','검사단계','측정방법','CTQ','검사기준 연결'],'qbm-ctq',7)}</div>
      <div data-pane="change" style="display:none"><div class="qbe-card-head"><h2>Revision / 변경관리</h2></div>${table(['Revision','적용일','변경 전','변경 후','변경사유','4M','작성자','승인상태'],'qbm-change',8)}</div>
      <div data-pane="lot" style="display:none"><div class="qbe-card-head"><h2>생산 LOT 적용 이력</h2></div>${table(['생산일','작업지시','생산 LOT','Revision','계획량','실적량','원료 LOT','PQC','OQC'],'qbm-lot',9)}</div>
    </div>
    <div class="qbe-card"><div class="qbe-card-head"><h2>다단계 BOM / 중간배치 구조</h2><span class="qbe-hint">완제품 → 중간배치 → 원료</span></div><div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-size:13px;font-weight:800"><span class="qbe-status blue">완제품</span><b>→</b><span class="qbe-status orange">중간배치 (선택)</span><b>→</b><span class="qbe-status green">원료 / 첨가제</span><span style="color:#64748b;font-weight:600">중간배치가 없는 제품은 원료를 완제품 BOM에 직접 연결합니다.</span></div></div>
  </div>`}
  function msg(t,tone='#2563eb'){const el=customHost?.querySelector('#qbm-message');if(el){el.textContent=t;el.style.color=tone;setTimeout(()=>{if(el.textContent===t)el.textContent=''},2500)}}
  function fields(){const o={};customHost.querySelectorAll('[data-f]').forEach(x=>o[x.dataset.f]=x.value.trim());return o}
  function setFields(r={}){customHost.querySelectorAll('[data-f]').forEach(x=>x.value=r[x.dataset.f]||'')}
  function render(){const rows=load();const p=customHost.querySelector('#qbm-products'),r=customHost.querySelector('#qbm-revisions');if(!rows.length){p.innerHTML=`<tr><td colspan="4" style="text-align:center;color:#94a3b8;padding:24px">${empty}</td></tr>`;r.innerHTML=`<tr><td colspan="7" style="text-align:center;color:#94a3b8;padding:24px">${empty}</td></tr>`;return}const products=[];const seen=new Set();rows.forEach(x=>{if(!seen.has(x.productCode)){seen.add(x.productCode);products.push(x)}});p.innerHTML=products.map(x=>`<tr data-select="${esc(x.id)}" style="cursor:pointer"><td>${esc(x.productCode)}</td><td>${esc(x.productName)}</td><td>${esc(x.customer)}</td><td>${esc(x.grade)}</td></tr>`).join('');r.innerHTML=rows.map(x=>`<tr data-select="${esc(x.id)}" style="cursor:pointer"><td>${esc(x.revision)}</td><td>${esc(x.changeNote)}</td><td>${esc(x.batchSize||'')}</td><td>${esc(x.yield||'')}</td><td>${esc(x.effectiveDate)}</td><td>${esc(x.status)}</td><td>${x.status==='승인'||x.status==='사용중'?'승인':'-'}</td></tr>`).join('')}
  function select(id){const row=load().find(x=>x.id===id);if(!row)return;selectedId=id;setFields(row);msg('BOM을 선택했습니다.');}
  function clearForm(){selectedId=null;setFields({status:'작성중'});msg('신규 BOM 입력 상태입니다.');}
  function saveRecord(){const v=fields();if(!v.productCode||!v.productName||!v.recipeNo||!v.revision){msg('제품코드, 제품명, Recipe No., Revision을 입력하세요.','#dc2626');return}let rows=load();if(selectedId){rows=rows.map(x=>x.id===selectedId?{...x,...v,updatedAt:new Date().toISOString()}:x)}else{selectedId='BOM-'+Date.now();rows.unshift({...v,id:selectedId,createdAt:new Date().toISOString()})}saveAll(rows);render();msg('BOM이 저장되었습니다.','#15803d')}
  function deleteRecord(){if(!selectedId){msg('삭제할 BOM을 먼저 선택하세요.','#dc2626');return}let rows=load().filter(x=>x.id!==selectedId);saveAll(rows);clearForm();render();msg('선택 BOM을 삭제했습니다.','#15803d')}
  function copyRecord(revisionMode){if(!selectedId){msg('복사할 BOM을 먼저 선택하세요.','#dc2626');return}const src=load().find(x=>x.id===selectedId);if(!src)return;const copy={...src,id:'BOM-'+Date.now(),status:'작성중',changeNote:revisionMode?'BOM 개정':''};if(revisionMode){const n=parseInt(String(src.revision||'').replace(/\D/g,''),10)||0;copy.revision='Rev.'+String(n+1).padStart(2,'0')}selectedId=copy.id;const rows=load();rows.unshift(copy);saveAll(rows);render();setFields(copy);msg(revisionMode?'신규 Revision을 생성했습니다.':'BOM을 복사했습니다.','#15803d')}
  function wire(){customHost.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{const id=b.dataset.tab;customHost.querySelectorAll('[data-pane]').forEach(p=>p.style.display=p.dataset.pane===id?'block':'none');customHost.querySelectorAll('[data-tab]').forEach(x=>x.style.background=x===b?'#2563eb':'#64748b')});customHost.addEventListener('click',e=>{const sel=e.target.closest('[data-select]');if(sel){select(sel.dataset.select);return}const b=e.target.closest('[data-bom-act]');if(!b)return;const a=b.dataset.bomAct;if(a==='search'){render();msg(load().length?'조회 완료':'조회 완료 · 등록된 BOM이 없습니다.');}else if(a==='add')clearForm();else if(a==='save')saveRecord();else if(a==='delete')deleteRecord();else if(a==='copy')copyRecord(false);else if(a==='revision')copyRecord(true);else if(a==='print')window.print()})}
  function mount(){const h=document.getElementById('qmes-business-extension-host');if(!h)return;const title=h.querySelector('.qbe-title,h1');if(!title||!title.textContent.includes('Recipe / BOM Master'))return;if(customHost&&document.body.contains(customHost))return;nativeHost=h;customHost=document.createElement('div');customHost.id='qmes-chemical-bom-v3-host';customHost.innerHTML=html();h.parentNode.insertBefore(customHost,h);h.style.display='none';wire();render()}
  function unmountIfNeeded(){if(!customHost)return;const recipeBtn=document.querySelector('[data-qbe-menu="recipe"] .qmes-top-menu-button.is-active,[data-qbe-menu="recipe"] button.is-active');const nativeStill=document.getElementById('qmes-business-extension-host');if(!recipeBtn||!nativeStill){customHost.remove();customHost=null;if(nativeHost&&document.body.contains(nativeHost))nativeHost.style.removeProperty('display');nativeHost=null}}
  new MutationObserver(()=>{mount();unmountIfNeeded()}).observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});
  document.addEventListener('click',e=>{if(e.target.closest('[data-qbe-menu="recipe"]'))setTimeout(mount,80);else if(e.target.closest('.qmes-top-menu-button'))setTimeout(unmountIfNeeded,80)},true);
  setInterval(()=>{mount();unmountIfNeeded()},700);
})();